    // ══════════════════════════════════════════════════════════════
    // ASSETS
    // ══════════════════════════════════════════════════════════════
    async function loadAssets() {
        if (!state.currentProject) return;
        try {
            const typeFilter = state.assetFilter ? '?type=' + state.assetFilter : '';
            const data = await api('/projects/' + state.currentProject.id + '/assets' + typeFilter);
            state.assets = data.assets || [];

            const groups = { images: ['keyframe', 'storyboard', 'thumbnail', 'reference_image', 'character_sheet'], video: ['video_raw', 'video_synced', 'video_final'], audio: ['audio_dialogue', 'audio_music', 'audio_sfx', 'audio_ambient', 'audio_mix', 'voice_sample'], other: ['lora_weights', 'subtitle', 'lut', 'other', 'export_package', 'fcpxml', 'edl', 'premiere_xml'] };
            const filterCats = [{ label: 'All', value: '' }, ...Object.entries(groups).map(([g]) => ({ label: g.charAt(0).toUpperCase() + g.slice(1), value: g }))];

            document.getElementById('assetFilters').innerHTML = filterCats.map(f =>
                `<button class="filter-pill ${f.value === state.assetFilter ? 'active' : ''}" onclick="filterAssets('${f.value}')">${f.label} (${f.value ? state.assets.filter(a => (groups[f.value] || []).includes(a.asset_type)).length : state.assets.length})</button>`
            ).join('');

            let filtered = state.assets;
            if (state.assetFilter && groups[state.assetFilter]) {
                filtered = state.assets.filter(a => groups[state.assetFilter].includes(a.asset_type));
            }

            document.getElementById('assetTableWrap').innerHTML = filtered.length === 0 ?
                `<div class="empty-state"><div class="icon">&#128230;</div><h3>No assets</h3><p>Register assets as they are generated.</p></div>` :
                `<table class="asset-table">
                    <tr><th>Type</th><th>Name</th><th>Format</th><th>Size</th><th>Date</th><th></th></tr>
                    ${filtered.map(a => `<tr>
                        <td><span class="badge">${esc(a.asset_type)}</span></td>
                        <td>${esc(a.file_name || a.file_path)}</td>
                        <td>${esc(a.format || '-')}</td>
                        <td>${a.size_bytes ? formatBytes(a.size_bytes) : '-'}</td>
                        <td class="text-muted">${new Date(a.created_at).toLocaleDateString()}</td>
                        <td><button class="btn btn-danger btn-sm" onclick="deleteAsset('${a.id}')">Del</button></td>
                    </tr>`).join('')}
                </table>`;
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    function filterAssets(group) { state.assetFilter = group; loadAssets(); }

    async function registerAsset() {
        if (!state.currentProject) return;
        const data = getModalData('assetModal');
        if (!data.file_path || !data.asset_type) return;
        try {
            await api('/projects/' + state.currentProject.id + '/assets', { method: 'POST', body: JSON.stringify(data) });
            closeModal('assetModal');
            clearModal('assetModal');
            loadAssets();
            setStatus('Asset registered');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function deleteAsset(id) {
        if (!confirm('Delete this asset?')) return;
        try {
            await api('/assets/' + id, { method: 'DELETE' });
            loadAssets();
            setStatus('Asset deleted');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    function formatBytes(bytes) {
        if (!bytes) return '0 B';
        const k = 1024;
        const sizes = ['B', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
    }
